/bin/bash -lc "menv python - <<'PY'
from hera.analysis import open_run,sdh_onset
r=open_run('data/6'); B=r.col('magnet_field'); R=r.col('sr1_X')/(r.col('sr0_X')/-1e6)
for hi in [4,5,6]:
 for deg in [3,5,7]:
  try:
   on=sdh_onset(R,B,b_hi=hi,f_min=4,bg_degree=deg,r_full_scale=5000)
   print(hi,deg,round(on.onset_b,3),[(round(t.freq,1),round(t.onset_b,2),t.censored,t.marginal) for t in on.tones[:4]])
  except Exception as e:print(e)
PY"

